-- Coder Nation Ops, phase 1: team accounts, CRM (clients, deals, activities, follow-ups) and proposals.
-- MySQL 8 / MariaDB 10.6+. Ids are UUIDs generated by the app. All timestamps are UTC.
-- Money is stored as integers in the currency's smallest unit (piastres, cents, halalas...), never as floats.

create table users (
  id char(36) not null primary key default (uuid()),
  -- utf8mb4_bin: the unique index and the lowercase check must both be exact, not case-insensitive.
  email varchar(254) character set utf8mb4 collate utf8mb4_bin not null unique,
  name varchar(80) not null,
  role varchar(20) not null,
  password_hash varchar(255) not null,
  active boolean not null default true,
  must_change_password boolean not null default false,
  created_at datetime(3) not null default current_timestamp(3),
  last_login_at datetime(3) null,
  constraint users_email_lower check (email = lower(email)),
  constraint users_name_len check (char_length(name) between 2 and 80),
  constraint users_role_ok check (role in ('owner', 'manager', 'employee'))
) default charset utf8mb4 collate utf8mb4_unicode_ci;

-- The browser holds a random token; only its SHA-256 is stored.
create table sessions (
  id char(36) not null primary key default (uuid()),
  user_id char(36) not null,
  token_hash varchar(64) not null unique,
  expires_at datetime(3) not null,
  created_at datetime(3) not null default current_timestamp(3),
  user_agent varchar(300) null,
  constraint sessions_user_fk foreign key (user_id) references users (id) on delete cascade,
  index sessions_user_idx (user_id),
  index sessions_expires_idx (expires_at)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

create table rate_limits (
  name varchar(200) not null primary key,
  hits int not null,
  window_start datetime(3) not null
) default charset utf8mb4 collate utf8mb4_unicode_ci;

-- One row: the company details printed on proposals.
create table company_settings (
  id smallint not null primary key default 1,
  name varchar(120) not null default '',
  address varchar(300) not null default '',
  email varchar(254) not null default '',
  phone varchar(40) not null default '',
  tax_number varchar(40) not null default '',
  updated_at datetime(3) not null default current_timestamp(3),
  constraint company_single_row check (id = 1)
) default charset utf8mb4 collate utf8mb4_unicode_ci;
insert into company_settings (id, name) values (1, 'Coder Nation');

create table clients (
  id char(36) not null primary key default (uuid()),
  name varchar(160) not null,
  phone varchar(30) null,
  email varchar(254) null,
  website varchar(200) null,
  notes varchar(4000) not null default '',
  created_by char(36) null,
  created_at datetime(3) not null default current_timestamp(3),
  constraint clients_name_len check (char_length(name) between 2 and 160),
  constraint clients_phone_len check (phone is null or char_length(phone) between 6 and 30),
  constraint clients_created_by_fk foreign key (created_by) references users (id) on delete set null,
  index clients_phone_idx (phone)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

create table contacts (
  id char(36) not null primary key default (uuid()),
  client_id char(36) not null,
  name varchar(120) not null,
  job_title varchar(120) null,
  phone varchar(30) null,
  email varchar(254) null,
  created_at datetime(3) not null default current_timestamp(3),
  constraint contacts_name_len check (char_length(name) between 2 and 120),
  constraint contacts_phone_len check (phone is null or char_length(phone) between 6 and 30),
  constraint contacts_client_fk foreign key (client_id) references clients (id) on delete cascade,
  index contacts_client_idx (client_id)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

create table deals (
  id char(36) not null primary key default (uuid()),
  client_id char(36) not null,
  contact_id char(36) null,
  title varchar(200) not null,
  service varchar(80) null,
  stage varchar(20) not null default 'new',
  source varchar(20) not null default 'manual',
  -- Set for deals that arrive from another system (the website's lead id): makes intake idempotent.
  external_id varchar(100) null unique,
  value_minor bigint null,
  currency char(3) null,
  owner_id char(36) null,
  lost_reason varchar(300) null,
  message varchar(2000) null,
  created_at datetime(3) not null default current_timestamp(3),
  updated_at datetime(3) not null default current_timestamp(3),
  stage_changed_at datetime(3) not null default current_timestamp(3),
  closed_at datetime(3) null,
  constraint deals_title_len check (char_length(title) between 2 and 200),
  constraint deals_stage_ok check (stage in ('new', 'contacted', 'meeting', 'proposal_sent', 'negotiation', 'won', 'lost')),
  constraint deals_source_ok check (source in ('website', 'manual', 'referral', 'other')),
  constraint deals_value_ok check (value_minor is null or value_minor >= 0),
  constraint deals_currency_ok check (currency is null or currency in ('EGP', 'USD', 'SAR', 'AED', 'EUR')),
  constraint deals_lost_reason_len check (lost_reason is null or char_length(lost_reason) between 2 and 300),
  -- A lost deal always says why; no other stage has a reason.
  constraint deals_lost_has_reason check ((stage = 'lost') = (lost_reason is not null)),
  constraint deals_closed_when_final check ((stage in ('won', 'lost')) = (closed_at is not null)),
  constraint deals_client_fk foreign key (client_id) references clients (id) on delete restrict,
  constraint deals_contact_fk foreign key (contact_id) references contacts (id) on delete set null,
  constraint deals_owner_fk foreign key (owner_id) references users (id) on delete set null,
  index deals_stage_idx (stage, stage_changed_at),
  index deals_owner_idx (owner_id),
  index deals_client_idx (client_id)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

create table activities (
  id char(36) not null primary key default (uuid()),
  deal_id char(36) not null,
  user_id char(36) null,
  kind varchar(20) not null,
  body varchar(4000) not null,
  created_at datetime(3) not null default current_timestamp(3),
  constraint activities_kind_ok check (kind in ('note', 'call', 'meeting', 'whatsapp', 'email', 'stage', 'system')),
  constraint activities_body_len check (char_length(body) between 1 and 4000),
  constraint activities_deal_fk foreign key (deal_id) references deals (id) on delete cascade,
  constraint activities_user_fk foreign key (user_id) references users (id) on delete set null,
  index activities_deal_idx (deal_id, created_at)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

create table follow_ups (
  id char(36) not null primary key default (uuid()),
  deal_id char(36) not null,
  assignee_id char(36) null,
  due_at datetime(3) not null,
  note varchar(500) not null default '',
  done_at datetime(3) null,
  created_at datetime(3) not null default current_timestamp(3),
  constraint follow_ups_deal_fk foreign key (deal_id) references deals (id) on delete cascade,
  constraint follow_ups_assignee_fk foreign key (assignee_id) references users (id) on delete set null,
  index follow_ups_open_idx (done_at, due_at)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

-- Proposals: numbered P-YYYY-NNNN, one counter row per year.
create table proposal_counters (
  year int not null primary key,
  last_number int not null
) default charset utf8mb4 collate utf8mb4_unicode_ci;

create table proposals (
  id char(36) not null primary key default (uuid()),
  deal_id char(36) not null,
  number varchar(30) not null unique,
  status varchar(20) not null default 'draft',
  title varchar(200) not null,
  currency char(3) not null,
  -- Basis points (14% = 1400). NULL = no tax line at all.
  tax_rate_bp int null,
  discount_minor bigint not null default 0,
  valid_until date null,
  intro varchar(4000) not null default '',
  -- [{ "title": "...", "body": "..." }] free text blocks of the technical proposal. The app always supplies both
  -- JSON documents (MySQL does not allow a literal default on a JSON column).
  sections json not null,
  -- [{ "title": "...", "weeks": 2 }]
  timeline json not null,
  created_by char(36) null,
  created_at datetime(3) not null default current_timestamp(3),
  updated_at datetime(3) not null default current_timestamp(3),
  sent_at datetime(3) null,
  constraint proposals_status_ok check (status in ('draft', 'sent', 'accepted', 'rejected')),
  constraint proposals_title_len check (char_length(title) between 2 and 200),
  constraint proposals_currency_ok check (currency in ('EGP', 'USD', 'SAR', 'AED', 'EUR')),
  constraint proposals_tax_ok check (tax_rate_bp is null or tax_rate_bp between 0 and 10000),
  constraint proposals_discount_ok check (discount_minor >= 0),
  constraint proposals_deal_fk foreign key (deal_id) references deals (id) on delete restrict,
  constraint proposals_created_by_fk foreign key (created_by) references users (id) on delete set null,
  index proposals_deal_idx (deal_id)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

create table proposal_items (
  id char(36) not null primary key default (uuid()),
  proposal_id char(36) not null,
  position int not null,
  title varchar(200) not null,
  description varchar(1000) not null default '',
  quantity int not null default 1,
  unit_price_minor bigint not null,
  constraint proposal_items_title_len check (char_length(title) between 1 and 200),
  constraint proposal_items_quantity_ok check (quantity between 1 and 10000),
  constraint proposal_items_price_ok check (unit_price_minor between 0 and 100000000000),
  constraint proposal_items_proposal_fk foreign key (proposal_id) references proposals (id) on delete cascade,
  index proposal_items_idx (proposal_id, position)
) default charset utf8mb4 collate utf8mb4_unicode_ci;

-- Payment schedule; percents are basis points and must add up to 10000 before a proposal can be exported.
create table proposal_milestones (
  id char(36) not null primary key default (uuid()),
  proposal_id char(36) not null,
  position int not null,
  title varchar(200) not null,
  percent_bp int not null,
  constraint proposal_milestones_title_len check (char_length(title) between 1 and 200),
  constraint proposal_milestones_percent_ok check (percent_bp between 1 and 10000),
  constraint proposal_milestones_proposal_fk foreign key (proposal_id) references proposals (id) on delete cascade,
  index proposal_milestones_idx (proposal_id, position)
) default charset utf8mb4 collate utf8mb4_unicode_ci;
